from pathlib import Path
import argparse,shutil
import pandas as pd,numpy as np
from select_onoff_stars import paired
from nba_api.stats.static import teams

def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path,default=Path(__file__).resolve().parent/'nba_passing_output');p.add_argument('--data-dir',type=Path);p.add_argument('--selection-rule',choices=['combined','possession_first','touches_first'],default='touches_first');a=p.parse_args(argv);root=a.output_dir;out=a.data_dir or root/'ball_control_dependency';out.mkdir(parents=True,exist_ok=True);metrics=pd.read_csv(root/'court_zone_networks/regressions/four_metrics.csv');metrics=metrics[metrics.season.eq('2024-25')].set_index('team');players=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv',dtype={'GAME_ID':str});games=pd.read_csv(root/'2025-26/team_season_topics/team_games.csv',dtype={'GAME_ID':str});games['date']=pd.to_datetime(games.GAME_DATE);coverage=[];rows=[];rankings=[]
 for t in teams.get_teams():
  team=t['abbreviation'];tid=t['id'];f=pd.read_csv(out/'tracking_2024-25'/(team+'.csv'));f['eligible_minutes']=f.MIN.ge(1000);f['team']=team;f['eligible_rank']=np.nan;f['touch_percentile']=np.nan;f['possession_percentile']=np.nan;f['ball_control_score']=np.nan;q=f[f.eligible_minutes].copy();assert len(q)>0,team
  for column,dest in [('TOUCHES','touch_percentile'),('TIME_OF_POSS','possession_percentile')]:q[dest]=(q[column].rank(method='average')-1)/(len(q)-1) if len(q)>1 else 1.
  q['ball_control_score']=(q.touch_percentile+q.possession_percentile)/2
  sort={'combined':['ball_control_score','TIME_OF_POSS','TOUCHES','PLAYER_ID'],'possession_first':['TIME_OF_POSS','TOUCHES','PLAYER_ID'],'touches_first':['TOUCHES','TIME_OF_POSS','PLAYER_ID']}[a.selection_rule];ascending=[False]*(len(sort)-1)+[True];eligible=q.sort_values(sort,ascending=ascending);eligible['eligible_rank']=range(1,len(q)+1)
  for col in ['eligible_rank','touch_percentile','possession_percentile','ball_control_score']:f.loc[eligible.index,col]=eligible[col]
  f['selection_rule']=a.selection_rule;rankings.append(f if a.selection_rule=='combined' else f.drop(columns=['touch_percentile','possession_percentile','ball_control_score']));leader=eligible.iloc[0];pid=int(leader.PLAYER_ID);player_name=leader.PLAYER_NAME;touches=float(leader.TOUCHES);time_poss=float(leader.TIME_OF_POSS);tracking_minutes=float(leader.MIN);score=float(leader.ball_control_score);touch_pct=float(leader.touch_percentile);poss_pct=float(leader.possession_percentile)
  g=games[games.TEAM_ID.eq(tid)].sort_values(['date','GAME_ID']);early=set(g.head(10).GAME_ID);part=players[players.TEAM_ID.eq(tid)&players.PLAYER_ID.eq(pid)];retained=part.GAME_ID.isin(early).any();c=dict(team=team,star_id=pid,star_name=player_name,prior_touches=touches,prior_time_of_possession=time_poss,prior_tracking_minutes=tracking_minutes,prior_ball_control_score=score,prior_touch_percentile=touch_pct,prior_possession_percentile=poss_pct,selection_rule=a.selection_rule,retained_first10=bool(retained),status='not_retained_first10')
  if not retained:coverage.append(c);continue
  other=players[players.PLAYER_ID.eq(pid)&players.TEAM_ID.ne(tid)];date=pd.to_datetime(other.GAME_DATE).min() if len(other) else pd.NaT;censor=date-pd.Timedelta(days=14) if pd.notna(date) else pd.NaT;window=g[g.date.lt(censor)] if pd.notna(censor) else g;played=set(part.GAME_ID);ngp=int(window.GAME_ID.isin(played).sum());absent=len(window)-ngp;c.update(present_games=ngp,absent_games=absent,status='available' if absent else 'no_observed_absence');coverage.append(c)
  if not absent:continue
  prior=paired(root/'onoff_dependency/onoff/2024-25'/(team+'.csv'));q=prior[prior.VS_PLAYER_ID.eq(pid)];assert len(q)==1;prior=q.iloc[0];cur=paired(root/'onoff_dependency/onoff/2025-26'/(team+'.csv'));cur=cur[cur.VS_PLAYER_ID.eq(pid)];assert len(cur)==1;cur=cur.iloc[0]
  rows.append(dict(team=team,team_id=tid,star_id=pid,star_name=player_name,prior_on_off_gap=prior.OFF_RATING_on-prior.OFF_RATING_off,prior_on_ortg=prior.OFF_RATING_on,prior_off_ortg=prior.OFF_RATING_off,prior_on_minutes=prior.MIN_on,prior_off_minutes=prior.MIN_off,current_on_off_gap=cur.OFF_RATING_on-cur.OFF_RATING_off,current_on_ortg=cur.OFF_RATING_on,current_off_ortg=cur.OFF_RATING_off,present_games=ngp,absent_games=absent,window_games=len(window),window_start=window.date.min().date().isoformat(),window_end=window.date.max().date().isoformat(),trade_censor_date=str(censor.date()) if pd.notna(censor) else '',first_other_team_date=str(date.date()) if pd.notna(date) else '',star_selection='2024-25 touches and time of possession; '+a.selection_rule+'; at least 1000 tracked minutes; strict leader',prior_touches=touches,prior_time_of_possession=time_poss,prior_tracking_minutes=tracking_minutes,prior_ball_control_score=score,prior_touch_percentile=touch_pct,prior_possession_percentile=poss_pct,selection_rule=a.selection_rule))
 pd.concat(rankings).to_csv(out/'all_ball_control_candidates.csv',index=False);covered=pd.DataFrame(coverage);d=pd.DataFrame(rows)
 if a.selection_rule!='combined':
  unused=['prior_ball_control_score','prior_touch_percentile','prior_possession_percentile'];covered=covered.drop(columns=unused);d=d.drop(columns=unused)
 covered.sort_values('team').to_csv(out/'coverage_all_30.csv',index=False);d=d.sort_values(['prior_on_off_gap','team'],ascending=[False,True]);d.insert(0,'dependency_rank',range(1,len(d)+1));d.to_csv(out/'selected_stars.csv',index=False);print(d[['team','star_name','prior_on_off_gap','present_games','absent_games','window_games']].to_string(index=False));print(pd.DataFrame(coverage).status.value_counts().to_string())
if __name__=='__main__':main()
